script:
frappe.ui.form.on("Book Doctype", {
    book_title: function(frm) {

        if (!frm.doc.book_title) return;

        frappe.call({
            method: "library_management2.api.get_book_info_ui",
            args: {
                book_title: frm.doc.book_title
            },
            callback: function(r) {
                console.log("SERVER RESPONSE:", r);

                if (!r.message) {
                    frappe.msgprint("No response from server.");
                    return;
                }

                frappe.msgprint(r.message);
            }
        });
    }
});
